insert into private_reports (id, campus_id, reporter_id, office, current_office, title, body, status, dont_share_name, resolution_note, created_at) values
  ('priv-housing', 'mit', 'user-ana', 'Housing', 'Housing', 'Roommate keeps leaving the door unlocked', 'My roommate keeps leaving our door unlocked overnight and I don''t feel safe.', 'Received', false, null, '2026-10-20T12:00:00.000Z'),
  ('priv-titleix', 'mit', 'user-cam', 'Title IX', 'Title IX', 'Harassing comments', 'Someone in my lab keeps making comments about my race.', 'Reviewing', true, null, '2026-10-19T12:00:00.000Z'),
  ('priv-facilities-lock', 'mit', 'user-ben', 'Facilities', 'Facilities', 'Lab storage room lock is broken', 'The lock on our lab''s chemical storage room (26-310) doesn''t latch. Anyone can walk in.', 'Received', false, null, '2026-10-23T12:00:00.000Z'),
  ('priv-housing-smoke', 'mit', 'bg-student-5', 'Housing', 'Housing', 'Neighbor smoking indoors every night', 'The resident in room 412 smokes in their room nightly; the smell comes into mine and I have asthma.', 'Reviewing', true, null, '2026-10-21T12:00:00.000Z'),
  ('priv-dean-conflict', 'mit', 'user-ben', 'Dean of Students', 'Dean of Students', 'Roommate conflict is escalating', 'My roommate and I can''t be in the room together anymore. It''s affecting my sleep and classes.', 'Received', false, null, '2026-10-22T12:00:00.000Z'),
  ('priv-dean-extension', 'mit', 'bg-student-6', 'Dean of Students', 'Dean of Students', 'Professor refused extension despite doctor''s note', 'I was hospitalized for a week and my professor won''t accept the note from MIT Medical.', 'Referred', false, 'Referred to Student Support Services, who will contact the instructor directly.', '2026-10-16T12:00:00.000Z'),
  ('priv-titleix-ta', 'mit', 'bg-student-7', 'Title IX', 'Title IX', 'Unwanted messages from a TA', 'A TA in one of my classes keeps messaging me late at night about non-class things.', 'Received', true, null, '2026-10-23T12:00:00.000Z'),
  ('priv-police-followed', 'mit', 'user-ana', 'Campus Police', 'Campus Police', 'Someone followed me near Building 10 at night', 'Around 11pm a man followed me from the Infinite Corridor exit to Mass Ave.', 'Reviewing', false, null, '2026-10-22T12:00:00.000Z'),
  ('priv-police-bike', 'mit', 'bg-student-8', 'Campus Police', 'Campus Police', 'Bike stolen from the dorm rack', 'My locked bike was taken from the rack outside Next House overnight. Lock was cut.', 'Resolved', false, null, '2026-10-15T12:00:00.000Z'),
  ('priv-access-elevator', 'mit', 'user-cam', 'Accessibility Services', 'Accessibility Services', 'Dorm elevator out, I use a wheelchair', 'The only elevator in my building has been out for two days and I can''t get to my room on floor 3.', 'Received', false, null, '2026-10-23T12:00:00.000Z'),
  ('priv-access-captions', 'mit', 'bg-student-9', 'Accessibility Services', 'Accessibility Services', 'No captions in my lecture recordings', 'My accommodation letter says recordings should be captioned, but none have been this term.', 'Reviewing', false, null, '2026-10-18T12:00:00.000Z'),
  ('priv-itsec-login', 'mit', 'bg-student-10', 'IT Security', 'IT Security', 'Someone logged into my account', 'I got a Duo push I didn''t request, then an email saying my password was changed.', 'Received', false, null, '2026-10-24T12:00:00.000Z'),
  ('priv-itsec-phish', 'mit', 'user-ana', 'IT Security', 'IT Security', 'Phishing email pretending to be MIT IST', 'An email asked me to ''verify my Kerberos'' on a non-MIT site. A few friends got it too.', 'Resolved', false, null, '2026-10-17T12:00:00.000Z')
insert into private_messages (id, report_id, author_role, author_id, body, created_at) values
  ('pm-titleix-1', 'priv-titleix', 'office', 'office-titleix', 'Thank you for reporting. We''re reviewing and will follow up.', '2026-10-19T12:00:00.000Z'),
  ('pm-police-1', 'priv-police-followed', 'office', 'staff-safety', 'Thanks for telling us. We''ve added patrols on that route tonight. Can you describe the person?', '2026-10-22T12:00:00.000Z'),
  ('pm-police-2', 'priv-police-followed', 'student', 'user-ana', 'Tall, dark jacket, grey backpack. He turned off near the 77 Mass Ave steps.', '2026-10-23T12:00:00.000Z'),
  ('pm-access-1', 'priv-access-captions', 'office', 'office-accessibility', 'We''ve contacted the course team; captioned versions should be up by Friday.', '2026-10-20T12:00:00.000Z')
insert into quick_fixes (id, campus_id, category, item, text) values
  ('qf-wifi-1', 'mit', 'IT', 'wifi', 'Forget the MIT network and reconnect, then re-accept the certificate.'),
  ('qf-wifi-2', 'mit', 'IT', 'wifi', 'Toggle Wi-Fi off and on; move within 10 m of an access point.'),
  ('qf-printer', 'mit', 'IT', 'printer', 'Open the front tray and clear any jammed sheet, then retry.'),
  ('qf-vending', 'mit', 'Dining', 'vending machine', 'Note the machine ID on the front panel for a refund request.'),
  ('qf-heater', 'mit', 'Facilities', 'heater', 'Check the thermostat is set above room temp and the vent isn''t blocked.')
